{
  "name": "@aria-plugins/aria-skills-marketplace",
  "version": "2.0.0",
  "description": "Interactive skills marketplace for opencode CLI \u2014 browse, install, and auto-update skills from a GitLab registry",
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.ts",
    "./rpc": "./src/rpc.ts"
  },
  "files": [
    "src"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "verify": "tsc -p tsconfig.verify.json && node .tmp-verify/verify/check.js",
    "dev": "tsc --noEmit --watch",
    "prepublishOnly": "npm run typecheck"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "skills",
    "marketplace",
    "gitlab"
  ],
  "author": "",
  "license": "MIT",
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "zod": "^4.1.8"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.32",
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.32",
    "@types/node": "^25.9.1",
    "typescript": "^6.0.3"
  }
}
